commands.command:
./ps.sh $'
foreach ($dir in "C:\fswth-spike\data", "Z:\") {
  $vhd = Join-Path $dir "attach-test.vhd"
  Remove-Item $vhd -ErrorAction SilentlyContinue
  & rust-img-vhd img $vhd create 67108864 --type fixed *> $null
  "create on ${dir}: exit $LASTEXITCODE"
  try {
    $img = Mount-DiskImage -ImagePath $vhd -NoDriveLetter -PassThru -ErrorAction Stop
    "attach on ${dir}: OK disk $((Get-DiskImage -ImagePath $vhd).Number)"
    Dismount-DiskImage -ImagePath $vhd | Out-Null
  } catch { "attach on ${dir}: FAILED $($_.Exception.Message.Trim())" }
  Remove-Item $vhd -ErrorAction SilentlyContinue
}'
